const status = String(msg.payload || "").trim();

if (status === "DA_KET_NOI_WIFI") {
    msg.payload = "🟢 Đã kết nối WiFi";
    msg.wifiConnected = true;
}
else if (status === "MAT_KET_NOI_WIFI") {
    msg.payload = "🔴 Mất kết nối WiFi";
    msg.wifiConnected = false;
}
else {
    msg.payload = "⚪ Không xác định";
    msg.wifiConnected = false;
}

return msg;

const p = msg.payload || {};

let source;
let chatId = null;
let question = "";

// ===============================
// CÂU HỎI TỪ DASHBOARD
// ===============================
if (p.source === "web") {

    source = "web";
    question = String(p.content || "").trim();

}
// ===============================
// CÂU HỎI TỪ TELEGRAM
// ===============================
else {

    source = "telegram";

    chatId =
        p.chatId ??
        msg.originalMessage?.chat?.id;

    question =
        String(
            p.content ??
            msg.originalMessage?.text ??
            ""
        ).trim();
}

if (!question) {
    return null;
}

msg.source = source;
msg.chatId = chatId;
msg.userQuestion = question;

// Lấy dữ liệu vườn mới nhất
const telemetry = global.get("latestTelemetry");

let gardenData;

if (telemetry) {
    gardenData = `
DỮ LIỆU VƯỜN HIỆN TẠI:
- Độ ẩm đất: ${telemetry.soil_percent}%
- Giá trị độ ẩm đất raw: ${telemetry.soil_raw}
- Nhiệt độ không khí: ${telemetry.temperature} °C
- Độ ẩm không khí: ${telemetry.air_humidity}%
- Cường độ ánh sáng raw: ${telemetry.light_raw}
- Máy bơm: ${telemetry.pump}
- Số lần tưới: ${telemetry.pump_count}
- Còi cảnh báo: ${telemetry.buzzer}
- WiFi RSSI: ${telemetry.wifi_rssi} dBm
`;
} else {
    gardenData = `
Hiện tại chưa nhận được dữ liệu cảm biến từ ESP32.
Nếu người dùng hỏi thông số hiện tại, hãy nói rằng hệ thống chưa có dữ liệu.
`;
}

const prompt = `
Bạn là trợ lý AI của hệ thống Vườn Thông Minh IoT nhóm 17.

${gardenData}

CÂU HỎI NGƯỜI DÙNG:
${question}

YÊU CẦU:
- Trả lời bằng tiếng Việt.
- Trả lời tự nhiên và ngắn gọn.
- Ưu tiên dữ liệu cảm biến hiện tại.
- Tuyệt đối không tự bịa số liệu cảm biến.
- Nếu người dùng hỏi có cần tưới hay không, hãy phân tích dựa trên độ ẩm đất.
- Nếu thiếu dữ liệu cần thiết, nói rõ là chưa có dữ liệu.
- Không sử dụng Markdown.
- Không dùng ký hiệu **, ##, ###, backtick hoặc dấu gạch đầu dòng Markdown.
- Trả lời như một trợ lý chat thông thường.
- Dễ đọc.
`;

msg.headers = {
    "Content-Type": "application/json"
};

msg.payload = JSON.stringify({
    model: "qwen3.5:9b",
    messages: [
        {
            role: "system",
            content: "Bạn là trợ lý chăm sóc Vườn Thông Minh IoT."
        },
        {
            role: "user",
            content: prompt
        }
    ],
    think: true,
    stream: false,
    keep_alive: "30m"
});

return msg;

let result = msg.payload;


// ============================================================
// PARSE RESPONSE TỪ OLLAMA
// ============================================================
if (typeof result === "string") {
    try {
        result = JSON.parse(result);
    } catch (e) {
        node.error("Không parse được JSON từ Ollama", msg);

        const errorDashboardMsg = {
            payload: {
                question: msg.userQuestion || "",
                answer: "Không thể đọc phản hồi từ AI. Vui lòng thử lại."
            }
        };

        return [null, errorDashboardMsg];
    }
}


// ============================================================
// LẤY CÂU TRẢ LỜI CỦA AI
// ============================================================
let answer = result?.message?.content;

if (!answer) {
    answer = "AI hiện chưa thể trả lời. Vui lòng thử lại.";
}


// ============================================================
// DỌN MARKDOWN NẾU AI VẪN SINH RA
// ============================================================
answer = String(answer)
    .replace(/\*\*/g, "")
    .replace(/###?/g, "")
    .replace(/`/g, "")
    .trim();


const question = String(msg.userQuestion || "").trim();


// ============================================================
// OUTPUT 1 -> TELEGRAM
// Chỉ gửi nếu câu hỏi ban đầu đến từ Telegram
// ============================================================
let telegramMsg = null;

if (msg.source === "telegram" && msg.chatId) {

    telegramMsg = {
        payload: {
            chatId: msg.chatId,
            type: "message",

            content:
                `🌱 TRỢ LÝ VƯỜN THÔNG MINH

👤 Câu hỏi:
${question}

🤖 Trợ lý:
${answer}`
        }
    };

}


// ============================================================
// OUTPUT 2 -> DASHBOARD
// Luôn cập nhật Dashboard dù câu hỏi đến từ Telegram hay Web
// ============================================================
const dashboardMsg = {
    payload: {
        question: question,
        answer: answer
    }
};


// ============================================================
// TRẢ RA 2 OUTPUT
//
// Output 1 -> Telegram Sender
// Output 2 -> ui-template Dashboard
// ============================================================
return [telegramMsg, dashboardMsg];

let data = msg.payload;

if (typeof data === "string") {
    try {
        data = JSON.parse(data);
    } catch (e) {
        node.error("Telemetry không phải JSON hợp lệ");
        return null;
    }
}

global.set("latestTelemetry", data);

node.status({
    fill: "green",
    shape: "dot",
    text: "Đã có dữ liệu vườn"
});

return msg;

const email = flow.get("report_email");

if (!email) {
    msg.payload =
        "Chưa có Email nhận báo cáo. Hãy đăng nhập trước.";

    msg.ui_update = {
        color: "#d32f2f",
        displayTime: 5,
        position: "top center",
        showCountdown: true
    };

    return [null, msg];
}

msg.to = String(email).trim();

return [msg, null];

const todayCount = Number(msg.payload);
const data = global.get("latestTelemetry") || {};

const now = new Date();

const time = now.toLocaleString("vi-VN", {
    timeZone: "Asia/Ho_Chi_Minh"
});

msg.topic = "Báo cáo Vườn Thông Minh IoT";

msg.payload =
    `BÁO CÁO VƯỜN THÔNG MINH IOT

Thời gian: ${time}

Số lần tưới hôm nay: ${todayCount} lần

Độ ẩm đất: ${data.soil_percent ?? "Chưa có dữ liệu"} %
Nhiệt độ: ${data.temperature ?? "Chưa có dữ liệu"} °C
Độ ẩm không khí: ${data.air_humidity ?? "Chưa có dữ liệu"} %
Ánh sáng: ${data.light_raw ?? "Chưa có dữ liệu"}
Máy bơm: ${data.pump ?? "Chưa có dữ liệu"}

Hệ thống Vườn Thông Minh IoT`;

return msg;

const count = Number(flow.get("email_today_count"));

const now = new Date();

const time = now.toLocaleTimeString("vi-VN", {
    timeZone: "Asia/Ho_Chi_Minh",
    hour: "2-digit",
    minute: "2-digit"
});

let logs = flow.get("notification_logs") || [];

const newLog = {
    time: time,
    type: "Email",
    content: `Báo cáo hôm nay: ${Number.isFinite(count) ? count : 0} lần tưới`,
    status: "Đã gửi"
};

// Thêm log mới lên đầu
logs.unshift(newLog);

// Chỉ giữ 5 log gần nhất
logs = logs.slice(0, 5);

// Lưu lại trong Node-RED
flow.set("notification_logs", logs);

// Gửi CẢ MẢNG sang ui-table
msg.payload = logs;

// Không giới hạn message cho riêng browser vừa bấm
delete msg._client;

return msg;

const count = Number(msg.payload);

if (!Number.isFinite(count)) {
    return null;
}

// Luôn lưu tổng số lần ESP32 đã bật bơm
flow.set("pump_total_current", count);

// Ngày hiện tại ở Việt Nam
const today = new Date().toLocaleDateString("en-CA", {
    timeZone: "Asia/Ho_Chi_Minh"
});

// Kiểm tra mốc đầu ngày
const baseline = Number(flow.get("pump_daily_baseline"));
const baselineDate = flow.get("pump_daily_baseline_date");

// Nếu Node-RED mới chạy hoặc sang ngày mới
// thì lấy tổng hiện tại làm mốc ban đầu
if (!Number.isFinite(baseline) || baselineDate !== today) {
    flow.set("pump_daily_baseline", count);
    flow.set("pump_daily_baseline_date", today);

    node.status({
        fill: "green",
        shape: "dot",
        text: "Mốc hôm nay: " + count
    });
}

msg.payload = count;

return msg;

const current = Number(flow.get("pump_total_current"));

if (!Number.isFinite(current)) {
    node.warn("Chưa nhận được pump/count từ ESP32");
    return null;
}

const today = new Date().toLocaleDateString("en-CA", {
    timeZone: "Asia/Ho_Chi_Minh"
});

flow.set("pump_daily_baseline", current);
flow.set("pump_daily_baseline_date", today);

msg.payload = {
    message: "Đã lưu mốc đầu ngày",
    baseline: current,
    date: today
};

return msg;

const current = Number(flow.get("pump_total_current"));
const baseline = Number(flow.get("pump_daily_baseline"));

if (!Number.isFinite(current)) {
    node.warn("Chưa nhận được tổng số lần tưới từ ESP32");
    return null;
}

if (!Number.isFinite(baseline)) {
    node.warn("Chưa có mốc đầu ngày");
    return null;
}

const todayCount = Math.max(0, current - baseline);

flow.set("email_today_count", todayCount);

msg.payload = todayCount;

return msg;

const form = msg.payload || {};

const username = String(form.username || "")
    .trim()
    .toLowerCase();

const email = String(form.email || "")
    .trim()
    .toLowerCase();

const password = String(form.password || "");
const confirmPassword = String(form.confirm_password || "");

function reject(message) {
    msg.payload = message;

    msg.ui_update = {
        color: "#d32f2f",
        displayTime: 5,
        position: "top center",
        showCountdown: true,
        allowDismiss: true,
        dismissText: "Đóng"
    };

    return [null, msg];
}

if (!username) {
    return reject("Vui lòng nhập tên đăng nhập.");
}

if (!email) {
    return reject("Vui lòng nhập email.");
}

if (!password) {
    return reject("Vui lòng nhập mật khẩu.");
}

if (!confirmPassword) {
    return reject("Vui lòng xác nhận mật khẩu.");
}

if (username.length < 4) {
    return reject("Tên đăng nhập phải có ít nhất 4 ký tự.");
}

if (!/^[a-z0-9_]+$/.test(username)) {
    return reject(
        "Tên đăng nhập chỉ được chứa chữ không dấu, số và dấu gạch dưới."
    );
}

if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)) {
    return reject("Email không đúng định dạng.");
}

if (password.length < 8) {
    return reject("Mật khẩu phải có ít nhất 8 ký tự.");
}

if (password !== confirmPassword) {
    return reject("Mật khẩu xác nhận không khớp.");
}

msg.registerForm = {
    username,
    email,
    password
};

msg.payload = null;

return [msg, null];

const form = msg.registerForm;
const rows = Array.isArray(msg.payload)
    ? msg.payload
    : [];

// Bỏ hàng tiêu đề
const users = rows.slice(1);

function reject(message) {
    delete msg.registerForm;

    msg.payload = message;

    msg.ui_update = {
        color: "#d32f2f",
        displayTime: 5,
        position: "top center",
        showCountdown: true,
        allowDismiss: true,
        dismissText: "Đóng"
    };

    return [null, msg];
}

if (!form) {
    return reject("Không tìm thấy dữ liệu đăng ký.");
}

const usernameExists = users.some(row =>
    String(row[1] || "").trim().toLowerCase() === form.username
);

if (usernameExists) {
    return reject("Tên đăng nhập đã tồn tại.");
}

const emailExists = users.some(row =>
    String(row[2] || "").trim().toLowerCase() === form.email
);

if (emailExists) {
    return reject("Email đã được đăng ký.");
}

const passwordHash = bcryptjs.hashSync(form.password, 10);

const userId = "USR-" + Date.now();

msg.payload = [
    userId,
    form.username,
    form.email,
    passwordHash,
    new Date().toISOString(),
    "active",
    ""
];

// Xóa mật khẩu gốc khỏi message
delete msg.registerForm;

return [msg, null];

msg.payload = "Đăng ký tài khoản thành công!";

msg.ui_update = {
    color: "#2e7d32",
    displayTime: 5,
    position: "top center",
    showCountdown: true,
    allowDismiss: true,
    dismissText: "Đóng"
};

return msg;

const form = msg.payload || {};

const username = String(form.username || "")
    .trim()
    .toLowerCase();

const password = String(form.password || "");

function reject(message) {
    msg.payload = message;

    msg.ui_update = {
        color: "#d32f2f",
        displayTime: 5,
        position: "top center",
        showCountdown: true
    };

    return [null, msg];
}

if (!username) {
    return reject("Vui lòng nhập tên đăng nhập.");
}

if (!password) {
    return reject("Vui lòng nhập mật khẩu.");
}

// Giữ thông tin để kiểm tra sau khi đọc Google Sheets
msg.loginForm = {
    username,
    password
};

msg.payload = null;

return [msg, null];

const form = msg.loginForm;

const rows = Array.isArray(msg.payload)
    ? msg.payload
    : [];

function reject(message) {
    delete msg.loginForm;

    msg.payload = message;

    msg.ui_update = {
        color: "#d32f2f",
        displayTime: 5,
        position: "top center",
        showCountdown: true
    };

    return [null, msg];
}

if (!form) {
    return reject("Không tìm thấy dữ liệu đăng nhập.");
}

// Bỏ hàng tiêu đề Google Sheets
const users = rows.slice(1);

// Tìm tài khoản theo username ở cột B, tức row[1]
const account = users.find(row =>
    String(row[1] || "")
        .trim()
        .toLowerCase() === form.username
);

if (!account) {
    return reject(
        "Tên đăng nhập hoặc mật khẩu không đúng."
    );
}

// Cột F là status, tức row[5]
const status = String(account[5] || "")
    .trim()
    .toLowerCase();

if (status !== "active") {
    return reject("Tài khoản hiện không hoạt động.");
}

// Cột D là password_hash, tức row[3]
const passwordHash = String(account[3] || "");

let passwordCorrect = false;

try {
    passwordCorrect = bcryptjs.compareSync(
        form.password,
        passwordHash
    );
} catch (error) {
    passwordCorrect = false;
}

if (!passwordCorrect) {
    return reject(
        "Tên đăng nhập hoặc mật khẩu không đúng."
    );
}

const loggedInUser = {
    user_id: String(account[0]),
    username: String(account[1]),
    email: String(account[2])
};

// Người đang đăng nhập
flow.set("logged_in_user", loggedInUser);

// Email dùng cho báo cáo định kỳ
// Logout KHÔNG xóa giá trị này
flow.set("report_email", loggedInUser.email);

msg.auth = loggedInUser;

delete msg.loginForm;

msg.payload =
    "Đăng nhập thành công. Chào " +
    msg.auth.username +
    "!";

msg.ui_update = {
    color: "#2e7d32",
    displayTime: 5,
    position: "top center",
    showCountdown: true
};

return [msg, null];

const AUTH_PAGE = "Tài khoản";
const SYSTEM_PAGE = "Hệ thống vườn";

// Output 1: hiện hệ thống và ẩn trang tài khoản
const visibilityMsg = {
    ...msg,
    payload: {
        pages: {
            show: [SYSTEM_PAGE],
            hide: [AUTH_PAGE]
        }
    }
};

// Output 2: chuyển sang trang hệ thống
const navigationMsg = {
    ...msg,
    payload: {
        page: SYSTEM_PAGE
    }
};

// Output 3: thông báo thành công
const notificationMsg = {
    ...msg,
    payload:
        "Đăng nhập thành công. Chào " +
        msg.auth.username +
        "!",
    ui_update: {
        color: "#2e7d32",
        displayTime: 5,
        position: "top center",
        showCountdown: true
    }
};

return [
    visibilityMsg,
    navigationMsg,
    notificationMsg
];

const feeds = msg.payload.feeds || [];

msg.payload = feeds
    .filter(row => row.field1 !== null)
    .map(row => ({
        time: Date.parse(row.created_at),
        value: Number(row.field1)
    }));

msg.topic = "Độ ẩm đất";
msg.action = "replace";

return msg;

// Lấy trạng thái mà nút đang nhớ.
// Trạng thái này cũng sẽ được đồng bộ từ ESP32.
let state = String(
    flow.get("pump_button_state") || "OFF"
).toUpperCase();

if (state !== "ON" && state !== "OFF") {
    state = "OFF";
}

// Đảo trạng thái
const nextState = state === "ON" ? "OFF" : "ON";

// Nhớ ngay trạng thái mới.
// Nhờ vậy nếu người dùng nhấn lần 2,
// Node-RED sẽ gửi OFF ngay mà không cần chờ 30 giây.
flow.set("pump_button_state", nextState);

// Payload gửi xuống MQTT
msg.payload = nextState;

return msg;

const state = String(msg.payload || "")
    .trim()
    .toUpperCase();

if (state !== "ON" && state !== "OFF") {
    return null;
}

// ========================================
// Đồng bộ trạng thái thật của ESP32
// với nút Toggle trên Node-RED
// ========================================
flow.set("pump_button_state", state);

// ========================================
// Kiểm tra trạng thái trước đó
// ========================================
const previousState = flow.get("last_pump_log_state");

// Lần đầu nhận retained state từ ESP32
// chỉ ghi nhớ, KHÔNG tạo log
if (previousState === undefined || previousState === null) {
    flow.set("last_pump_log_state", state);
    return null;
}

// Không thay đổi thì không log
if (previousState === state) {
    return null;
}

flow.set("last_pump_log_state", state);

// ========================================
// Tạo nhật ký
// ========================================
const now = new Date();

const time = now.toLocaleTimeString("vi-VN", {
    timeZone: "Asia/Ho_Chi_Minh",
    hour: "2-digit",
    minute: "2-digit"
});

let logs = flow.get("notification_logs") || [];

logs.unshift({
    time: time,
    type: "Bơm nước",
    content:
        state === "ON"
            ? "Đã kích hoạt tưới nước"
            : "Đã dừng tưới nước",
    status:
        state === "ON"
            ? "Đã bật"
            : "Đã tắt"
});

logs = logs.slice(0, 5);

flow.set("notification_logs", logs);

msg.payload = logs;

// Cho mọi browser đang mở đều cập nhật
delete msg._client;

return msg;

const moisture = Number(msg.payload);

msg.topic = "Cảnh báo Vườn Thông Minh";

msg.payload =
    `Cảnh báo: Độ ẩm đất hiện chỉ còn ${moisture}%. Cây cần được kiểm tra và tưới nước.`;

return msg;

const moisture = Number(msg.payload);

if (!Number.isFinite(moisture)) {
    return null;
}

const now = new Date();

const time = now.toLocaleTimeString("vi-VN", {
    timeZone: "Asia/Ho_Chi_Minh",
    hour: "2-digit",
    minute: "2-digit"
});

let logs = flow.get("notification_logs") || [];

logs.unshift({
    time: time,
    type: "Pushover",
    content: `Cảnh báo độ ẩm đất thấp: ${moisture}%`,
    status: "Đã gửi"
});

logs = logs.slice(0, 5);

flow.set("notification_logs", logs);

msg.payload = logs;

delete msg._client;

return msg;

const currentState = String(msg.payload || "").trim();

if (!currentState) {
    return null;
}

const previousState = flow.get("last_light_status");

// Lần đầu tiên chỉ ghi nhớ trạng thái, không tạo log
if (previousState === undefined || previousState === null) {
    flow.set("last_light_status", currentState);
    return null;
}

// Không thay đổi thì bỏ qua
if (previousState === currentState) {
    return null;
}

// Có thay đổi
flow.set("last_light_status", currentState);

const now = new Date();

const time = now.toLocaleTimeString("vi-VN", {
    timeZone: "Asia/Ho_Chi_Minh",
    hour: "2-digit",
    minute: "2-digit"
});

let logs = flow.get("notification_logs") || [];

logs.unshift({
    time: time,
    type: "Ánh sáng",
    content: `${previousState} → ${currentState}`,
    status: "Đã thay đổi"
});

logs = logs.slice(0, 5);

flow.set("notification_logs", logs);

msg.payload = logs;

delete msg._client;

return msg;

// Xóa trạng thái đăng nhập
flow.set("logged_in_user", null);

// KHÔNG xóa report_email
// để báo cáo Email tự động vẫn hoạt động.

// Output 1:
// Ẩn trang hệ thống, hiện trang tài khoản
const visibilityMsg = {
    ...msg,
